import { createHTTPServer } from '@trpc/server/adapters/standalone';
import { z } from 'zod';
import { createServer } from 'http';

const t = initTRPC.create();
const publicProcedure = t.procedure;

const appRouter = t.router({
  countdown: publicProcedure
    .input(z.number())
    .subscription(async function* (opts) {
      console.log('Generator function called with input:', opts.input);
      const { n } = opts.input;
      for (let i = n; i >= 0; i--) {
        console.log('About to await for i=' + i);
        await new Promise((resolve) => setTimeout(resolve, 100));
        console.log('Yielding: ' + i);
        yield i;
      }
      console.log('Generator function done');
    }),
});

export type AppRouter = typeof appRouter;

const server = createHTTPServer({
  router: appRouter,
  onError: ({ error, path }) => {
    console.error('Server error:', error.message, 'path:', path, 'stack:', error.stack);
  },
});

server.listen(3000, () => {
  console.log('Server listening on port 3000');
});
